const TEAMS = { w2: { at: +process.env.TEAM_W2_AT || Date.UTC(2026, 10, 25, 12, 0, 0), end: +process.env.TEAM_W2_END || Date.UTC(2026, 11, 2, 12, 0, 0) } };
